function parseRawSseEvent(raw: string): ReplayEvent | null {
  let text = String(raw ?? "").trim();
  if (!text) return null;

  if (
    (text.startsWith("'") && text.endsWith("'")) ||
    (text.startsWith('"') && text.endsWith('"'))
  ) {
    text = text.slice(1, -1);
  }

  const dataIndex = text.indexOf("data:");
  if (dataIndex === -1) return null;

  const payloadText = text.slice(dataIndex + 5).trim();
  const jsonStart = payloadText.indexOf("{");
  const jsonEnd = payloadText.lastIndexOf("}");
  if (jsonStart === -1 || jsonEnd === -1 || jsonEnd < jsonStart) {
    return null;
  }

  const candidate = payloadText.slice(jsonStart, jsonEnd + 1);
  const attempts = [
    candidate,
    candidate.replace(/\\"/g, '"'),
    candidate.replace(/\\"/g, '"').replace(/\\\\n/g, "\\n"),
    candidate.replace(/\\"/g, '"').replace(/\\'/g, "'"),
    candidate
      .replace(/\\"/g, '"')
      .replace(/\\\\n/g, "\\n")
      .replace(/\\'/g, "'"),
  ];

  for (const attempt of attempts) {
    try {
      return JSON.parse(attempt) as ReplayEvent;
    } catch {
      continue;
    }
  }

  return null;
}

function upsertSubagent(
  items: SubagentItem[],
  id: string,
  update: (current: SubagentItem) => SubagentItem,
): SubagentItem[] {
  const index = items.findIndex((item) => item.id === id);
  const current = index >= 0 ? items[index] : { id, tools: [], interrupts: [] };
  const next = update(current);

  if (index === -1) {
    return [...items, next];
  }

  const cloned = [...items];
  cloned[index] = next;
  return cloned;
}

function upsertTool(
  tools: NonNullable<SubagentItem["tools"]>,
  toolId: string,
  update: (current: NonNullable<SubagentItem["tools"]>[number]) => NonNullable<SubagentItem["tools"]>[number],
) {
  const index = tools.findIndex((tool) => tool.id === toolId);
  const current = index >= 0 ? tools[index] : { id: toolId, name: toolId };
  const next = update(current);

  if (index === -1) {
    return [...tools, next];
  }

  const cloned = [...tools];
  cloned[index] = next;
  return cloned;
}

function resolvePublicTaskId(
  wrapper: Record<string, any>,
  inner: ReplayEvent | null,
  context: ReplayContext,
): string {
  const runtimeTaskId = String(wrapper.task_id ?? "");
  const beforeAgentNamespace =
    inner?.type === "CUSTOM" && inner?.name === "BEFORE_AGENT_EVENT"
      ? String(inner.value?.metadata?.namespace ?? "")
      : "";

  if (beforeAgentNamespace) {
    context.runtimeTaskToPublicId.set(runtimeTaskId, beforeAgentNamespace);
    return beforeAgentNamespace;
  }

  return context.runtimeTaskToPublicId.get(runtimeTaskId) || runtimeTaskId;
}

function applyReplayEvent(
  items: SubagentItem[],
  event: ReplayEvent,
  context: ReplayContext,
): SubagentItem[] {
  if (event.type !== "CUSTOM") return items;

  if (event.name === "TASK_SUBAGENT" && event.value) {
    const publicId = String(event.value.task_id ?? "");
    const type = String(event.value.subagent_type ?? "");
    const description = String(event.value.description ?? "");

    return upsertSubagent(items, publicId, (current) => ({
      ...current,
      id: publicId,
      label: current.label || toTitleCase(type),
      type: current.type || type,
      description: current.description || description,
    }));
  }

  if (event.name !== "SUBAGENT_EVENT" || !event.value) {
    return items;
  }

  const wrapper = event.value;
  const namespace = Array.isArray(wrapper.namespace)
    ? wrapper.namespace.join(" / ")
    : undefined;
  const wrapperEvent = wrapper.event as Record<string, any> | undefined;
  const inner =
    wrapperEvent?.type === "RAW_SSE_EVENT"
      ? parseRawSseEvent(String(wrapperEvent.raw_sse ?? ""))
      : (wrapperEvent as ReplayEvent | undefined) ?? null;
  const publicId = resolvePublicTaskId(wrapper, inner, context);

  return upsertSubagent(items, publicId, (current) => {
    const next: SubagentItem = {
      ...current,
      id: publicId,
      label: current.label || toTitleCase(current.type),
      namespace: current.namespace || namespace,
      tools: [...(current.tools ?? [])],
      interrupts: [...(current.interrupts ?? [])],
    };

    if (!inner) {
      return next;
    }

    if (inner.type === "CUSTOM" && inner.name === "BEFORE_AGENT_EVENT") {
      const prompt = String(inner.value?.message ?? "");
      next.prompt = prompt || next.prompt;
      next.description = next.description || prompt;
      return next;
    }

    if (inner.type === "CUSTOM" && inner.name === "HITL_INTERRUPT") {
      next.interrupts = [
        ...(next.interrupts ?? []),
        {
          threadId: String(inner.value?.thread_id ?? "thread"),
          content: inner.value?.interrupt,
        },
      ];
      return next;
    }

    switch (inner.type) {
      case "TEXT_MESSAGE_CHUNK":
      case "TEXT_MESSAGE_CONTENT": {
        next.text = `${next.text ?? ""}${String((inner as any).delta ?? "")}`;
        return next;
      }

      case "TOOL_CALL_START": {
        const toolId = String((inner as any).toolCallId ?? "");
        next.tools = upsertTool(next.tools ?? [], toolId, (tool) => ({
          ...tool,
          id: toolId,
          name: String((inner as any).toolCallName ?? tool.name ?? toolId),
          status: "running",
        }));
        return next;
      }

      case "TOOL_CALL_ARGS": {
        const toolId = String((inner as any).toolCallId ?? "");
        next.tools = upsertTool(next.tools ?? [], toolId, (tool) => ({
          ...tool,
          id: toolId,
          args: `${tool.args ?? ""}${String((inner as any).delta ?? "")}`,
        }));
        return next;
      }

      case "TOOL_CALL_RESULT": {
        const toolId = String((inner as any).toolCallId ?? "");
        const resultChunk = String((inner as any).content ?? "");
        next.tools = upsertTool(next.tools ?? [], toolId, (tool) => ({
          ...tool,
          id: toolId,
          status: "completed",
          result: tool.result ? `${tool.result}\n\n${resultChunk}` : resultChunk,
        }));
        return next;
      }

      case "TOOL_CALL_END": {
        const toolId = String((inner as any).toolCallId ?? "");
        next.tools = upsertTool(next.tools ?? [], toolId, (tool) => ({
          ...tool,
          id: toolId,
          status: "completed",
        }));
        return next;
      }

      default:
        return next;
    }
  });
}

export default function Test() {
  const [expanded, setExpanded] = useState(false);
  const [replayedSubagents, setReplayedSubagents] = useState<SubagentItem[]>([]);
  const [currentMessage, setCurrentMessage] = useState("");
  const [dictationStatus, setDictationStatus] = useState<DictationStatus>("idle");
  const [isPlanContainerExpanded, setIsPlanContainerExpanded] = useState(false);
  const [isPlanCardExpanded, setIsPlanCardExpanded] = useState(false);
  const [planIndex, setPlanIndex] = useState(0);
  const timerRef = useRef<number | null>(null);
  const planTimerRef = useRef<number | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const composerContainerRef = useRef<HTMLDivElement>(null);
  const replayEvents = useMemo(() => STREAM0_REPLAY_EVENTS, []);
  const activePlan = DUMMY_PLAN_SNAPSHOTS[planIndex] ?? null;

  useEffect(() => {
    const context: ReplayContext = {
      runtimeTaskToPublicId: new Map(),
    };

    let cancelled = false;
    let currentItems: SubagentItem[] = [];

    const clearTimer = () => {
      if (timerRef.current !== null) {
        window.clearTimeout(timerRef.current);
        timerRef.current = null;
      }
    };

    const schedule = (fn: () => void, delay: number) => {
      clearTimer();
      timerRef.current = window.setTimeout(fn, delay);
    };

    const runStep = (index: number) => {
      if (cancelled) return;

      if (index < replayEvents.length) {
        currentItems = applyReplayEvent(currentItems, replayEvents[index], context);
        setReplayedSubagents(currentItems);
        schedule(() => runStep(index + 1), 100);
        return;
      }

      schedule(() => {
        if (cancelled) return;
        context.runtimeTaskToPublicId.clear();
        currentItems = [];
        setReplayedSubagents([]);
        runStep(0);
      }, 15000);
    };

    clearTimer();
    runStep(0);

    return () => {
      cancelled = true;
      clearTimer();
    };
  }, [replayEvents]);

  useEffect(() => {
    const clearPlanTimer = () => {
      if (planTimerRef.current !== null) {
        window.clearTimeout(planTimerRef.current);
        planTimerRef.current = null;
      }
    };

    const tick = () => {
      setPlanIndex((current) => (current + 1) % DUMMY_PLAN_SNAPSHOTS.length);
      planTimerRef.current = window.setTimeout(tick, 1600);
    };

    clearPlanTimer();
    planTimerRef.current = window.setTimeout(tick, 1600);

    return () => {
      clearPlanTimer();
    };
  }, []);

  return (
    <div className="relative min-h-screen overflow-hidden bg-background text-foreground">
      <div className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_top,_hsl(var(--primary)/0.14),_transparent_28%)]" />
      <div className="pointer-events-none absolute inset-0 bg-gradient-to-b from-background via-background to-black/20" />
      <div className="mx-auto flex min-h-screen w-full max-w-7xl items-center justify-center px-6 py-16 pb-56">
        <div className="w-full max-w-5xl space-y-8">
          {activePlan ? (
            <PlanningContainer
              plan={activePlan}
              expanded={isPlanContainerExpanded}
              onToggle={() => setIsPlanContainerExpanded((prev) => !prev)}
              title="Deep agent execution plan"
            />
          ) : null}

          <SubagentContainer
            subagents={replayedSubagents}
            expanded={expanded}
            onToggle={() => setExpanded((current) => !current)}
            title="Delegated subagents"
          />

          <div className="space-y-4">
            {replayedSubagents.map((subagent, index) => (
              <SubagentCard
                key={`standalone-${subagent.id}`}
                subagent={subagent}
                index={index}
              />
            ))}
          </div>

          <TooltipProvider>
            <div className="px-2">
              <ChatInputBar
                attachments={[]}
                isMessagesEmpty={false}
                positionClass="fixed bottom-8 left-1/2 z-20 w-[min(calc(100%-1.5rem),56rem)] -translate-x-1/2"
                isPrivateMode={false}
                thinkingActive={false}
                isStreaming={false}
                currentMessage={currentMessage}
                setCurrentMessage={setCurrentMessage}
                handlePaste={() => {}}
                handleSendMessage={() => {}}
                handleStopStreaming={() => {}}
                isImageFile={() => false}
                getImageUrl={() => ""}
                handleImageClick={() => {}}
                removeAttachment={() => {}}
                handleFileUpload={() => {}}
                fileInputRef={fileInputRef}
                textareaRef={textareaRef}
                containerRef={composerContainerRef}
                emptyWrapperStyle={undefined}
                textareaMaxHeight={220}
                onDictationSubmit={() => {}}
                onDictationStatusChange={setDictationStatus}
                dictationStatus={dictationStatus}
                AgentIcon={Building2}
                Tooltip={Tooltip}
                TooltipTrigger={TooltipTrigger}
                TooltipContent={TooltipContent}
                currentAgent={{
                  name: "Deep Agent",
                  description: "Replay the input container together with a changing plan snapshot.",
                }}
                Textarea={Textarea}
                topAccessory={
                  activePlan ? (
                    <PlanCard
                      plan={activePlan}
                      expanded={isPlanCardExpanded}
                      onToggle={() => setIsPlanCardExpanded((prev) => !prev)}
                      title="Deep agent execution plan"
                      className="absolute bottom-[calc(100%-1px)] left-1/2 z-10 w-[min(100%,39rem)] -translate-x-1/2"
                    />
                  ) : null
                }
              />
            </div>
          </TooltipProvider>
        </div>
      </div>
    </div>
  );
}
